SELECT M.file_seq AS fileSeq, M.file_original_nm AS fileOriginalNm, CONCAT(R.repository_url, '/', M.file_nm) AS fileUrl FROM utb_file_mst M LEFT JOIN utb_file_repository R ON M.file_repository_seq = R.file_repository_seq AND R.del_yn = 'N' WHERE M.file_seq IN
#{seq}
AND M.del_yn = 'N'
